select c.command_id, c.tree_id, c.category_node_id, n.node_name as category_node_name, c.command_code, c.command_name, c.command_type, c.command_template, c.status, c.create_time, c.remark from biz_command_config c left join biz_tree_node n on n.node_id = c.category_node_id and n.del_flag = '0'
c.del_flag = '0'
and c.command_code like concat('%', #{bo.commandCode}, '%')
and c.command_name like concat('%', #{bo.commandName}, '%')
and c.command_type = #{bo.commandType}
and c.tree_id = #{bo.treeId}
and c.category_node_id = #{bo.categoryNodeId}
and c.status = #{bo.status}
order by c.create_time desc, c.command_id desc

